pub fn swap_halves(v: &mut [i32]) {
    let n = v.len() / 2;
    let left = &mut v[..n];
    let right = &mut v[n..];
    for i in 0..n {
        std::mem::swap(&mut left[i], &mut right[i]);
    }
}

pub fn run() -> Vec<i32> {
    let mut v = vec![1, 2, 3, 4, 5, 6];
    swap_halves(&mut v);
    v
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn swaps_six() {
        assert_eq!(run(), vec![4, 5, 6, 1, 2, 3]);
    }
    #[test]
    fn odd_length_leaves_the_last_one() {
        let mut v = vec![1, 2, 3, 4, 5];
        swap_halves(&mut v);
        assert_eq!(v, vec![3, 4, 1, 2, 5]);
    }
}

