pub fn swap_halves(v: &mut [i32]) {
    let n = v.len() / 2;
    let (left, right) = v.split_at_mut(n);
    for i in 0..n {
        std::mem::swap(&mut left[i], &mut right[i]);
    }
}

pub fn run() -> Vec<i32> {
    let mut v = vec![1, 2, 3, 4, 5, 6];
    swap_halves(&mut v);
    v
}

