pub fn reverse_in_place(v: &[i32]) {
    let n = v.len();
    for i in 0..n / 2 {
        v.swap(i, n - 1 - i);
    }
}

pub fn run() -> Vec<i32> {
    let mut v = vec![1, 2, 3, 4, 5];
    reverse_in_place(&v);
    v
}

